            self.item = re.compile(self.item)
        except TypeError as e:
            raise TypeError(f"The passed item of {self.item} is not usable for regex: {e}") from None

    self.match_string = match_string

    self.__search(obj, self.item, parents_ids=frozenset({id(obj)}))

    empty_keys = [k for k, v in self.items() if not v]

